let tripEditing='',tripCache=[],tripProposalLimit=60,archivedTrips=false;
async function renderTrips(ticket){
 $('title').textContent=archivedTrips?'Archived trips':'Trips';$('subtitle').textContent=archivedTrips?'Restore a trip with its dates and review decisions intact.':'Your trips and suggested visits from recorded places and dates.';
 try{const data=await api('/api/trips'+(archivedTrips?'?archived=1':''));if(ticket!==requestId)return;tripCache=data.trips;
 const cards=(rows,suggested)=>rows.map(t=>`<article class="place-card">${t.cover?`<img loading="lazy" src="/preview/${t.cover}" alt="">`:''}<strong>${escape(t.name)}</strong><small>${escape(t.after)} – ${escape(t.before)} · ${number(t.count)} files</small><div style="padding:0 14px 14px;display:flex;gap:8px"><button class="chip" data-trip-open="${t.id}">Browse</button><button class="outline" data-trip-edit="${t.id}" data-suggested="${suggested}">${suggested?'Save as trip':'Edit trip'}</button>${suggested?'':`<button class="outline" data-trip-archive="${t.id}">${archivedTrips?'Restore':'Archive'}</button>`}</div></article>`).join('');
 $('content').innerHTML='<div class="collection-actions"><button class="primary" id="newTrip">New trip</button><button class="outline" id="toggleArchivedTrips">'+(archivedTrips?'Back to trips':'Archived trips')+'</button></div><div class="places">'+cards(data.trips,false)+'</div>'+(archivedTrips?'':'<div class="group-head"><h2>Suggested visits</h2><span>'+number(data.proposals.length)+' suggestions</span></div><p class="local-note">'+escape(data.meaning)+'</p><div class="places">'+cards(data.proposals.slice(0,tripProposalLimit),true)+'</div>'+(data.proposals.length>tripProposalLimit?'<button class="outline" id="moreTrips" style="margin:20px 0">More suggestions</button>':''));
 $('newTrip').onclick=()=>editTrip();$('toggleArchivedTrips').onclick=()=>{archivedTrips=!archivedTrips;load()};
 $('content').querySelectorAll('[data-trip-archive]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await saveOrganization(archivedTrips?'restore_trip':'archive_trip',{trip:b.dataset.tripArchive});await load()}catch(e){notify(e.message);b.disabled=false}});if($('moreTrips'))$('moreTrips').onclick=()=>{tripProposalLimit+=60;renderTrips(requestId)};
 const all=[...data.trips,...data.proposals];
 $('content').querySelectorAll('[data-trip-open]').forEach(b=>b.onclick=()=>{const t=all.find(t=>t.id===b.dataset.tripOpen);state.view='photos';state.collectionName=t.name;state.person='';state.place=t.place;state.trip=data.trips.some(x=>x.id===t.id)?t.id:'';state.query='';state.filter='all';state.year='';state.after=t.after;state.before=t.before;state.selecting=false;selection.clear();$('query').value='';$('year').value='';$('after').value=t.after;$('before').value=t.before;load()});
 $('content').querySelectorAll('[data-trip-edit]').forEach(b=>b.onclick=()=>editTrip(all.find(t=>t.id===b.dataset.tripEdit),b.dataset.suggested==='true'));
 }catch{$('content').innerHTML='<div class="empty">Trips could not be loaded. Try again.</div>'}
}
