 $('personChoice').value=onlyCreate?'':preferredPerson;$('personChoice').parentElement.hidden=onlyCreate||!!rename;$('personName').parentElement.hidden=!rename&&!onlyCreate&&!!$('personChoice').value;$('personName').value=rename?peopleCache.find(p=>p.id===rename).name:'';$('personError').textContent='';$('personDialog').showModal();$('personName').focus();
